<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetTypeVO;

trait ThemeAssetTypeAccessor
{
    private ThemeAssetTypeVO $_type;
    public function getType(): string
    {
        return $this->_type->value();
    }
    public function type(): ThemeAssetTypeVO
    {
        return $this->_type;
    }
    public function isTypeChanged(?self $original = null): bool
    {
        return !$this->_type->equals($original?->_type);
    }
    public function withType(ThemeAssetTypeVO|string $type): self
    {
        $copy = clone $this;
        $copy->_type = ThemeAssetTypeVO::from($type);
        return $copy;
    }
}
